// ─── File: src/main/java/com/bank/transfer/service/TransferService.java ───
package com.bank.transfer.service;

import com.bank.transfer.dto.*;
import com.bank.transfer.exception.*;
import com.bank.transfer.model.Account;
import com.bank.transfer.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.UUID;

@Service
@RequiredArgsConstructor  // Lombok generates constructor for all final fields
@Slf4j                    // Lombok generates: private static final Logger log = ...
public class TransferService {

    // Dependencies injected via constructor (IoC in action!)
    // Spring resolves AccountRepository → the JPA proxy implementation
    private final AccountRepository accountRepo;

    /**
     * Transfer funds between two accounts.
     * @Transactional ensures atomicity — both debit AND credit succeed, or neither does.
     */
    @Transactional
    public TransferResponse transfer(TransferRequest request) {
        log.info("Transfer request: Rs.{} from {} to {}",
            request.amount(), request.fromAccountId(), request.toAccountId());

        // Find accounts with pessimistic lock (prevents concurrent modification)
        Account fromAccount = accountRepo.findByIdForUpdate(request.fromAccountId())
            .orElseThrow(() -> new AccountNotFoundException(request.fromAccountId()));

        Account toAccount = accountRepo.findByIdForUpdate(request.toAccountId())
            .orElseThrow(() -> new AccountNotFoundException(request.toAccountId()));

        // Business logic: validate and transfer
        if (fromAccount.getBalance().compareTo(request.amount()) < 0) {
            throw new InsufficientBalanceException(
                request.fromAccountId(), fromAccount.getBalance(), request.amount());
        }

        fromAccount.debit(request.amount());
        toAccount.credit(request.amount());

        // JPA dirty checking auto-saves — but explicit save is clearer
        accountRepo.save(fromAccount);
        accountRepo.save(toAccount);

        String transferId = "TXF-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();

        log.info("Transfer {} completed: {} balance={}, {} balance={}",
            transferId, request.fromAccountId(), fromAccount.getBalance(),
            request.toAccountId(), toAccount.getBalance());

        return new TransferResponse(
            transferId,
            request.fromAccountId(),
            request.toAccountId(),
            request.amount(),
            "COMPLETED",
            LocalDateTime.now()
        );
    }
}
