// ─── File: src/main/java/com/bank/pricefeed/service/PriceFeedService.java ───
package com.bank.pricefeed.service;

import com.bank.pricefeed.config.PriceFeedConfig;
import com.bank.pricefeed.model.Symbol;
import com.bank.pricefeed.repository.SymbolRepository;
import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Service
@RequiredArgsConstructor
@Slf4j
public class PriceFeedService {

    // ─── Dependencies injected by IoC (Phase 2-3 of lifecycle) ───
    private final SymbolRepository symbolRepo;
    private final PriceFeedConfig config;

    // ─── Mutable state managed by lifecycle hooks ───
    private final Map<String, BigDecimal> priceCache = new ConcurrentHashMap<>();
    private volatile boolean connected = false;

    /**
     * Phase 6a: @PostConstruct — runs AFTER all dependencies are injected.
     * Safe to use symbolRepo and config here.
     * Keep it FAST — no blocking external calls that might timeout.
     */
    @PostConstruct
    void init() {
        log.info("[LIFECYCLE] @PostConstruct — initializing PriceFeedService");

        // Step 1: Load active symbols from DB into cache
        List<Symbol> activeSymbols = symbolRepo.findByActiveTrue();
        log.info("[LIFECYCLE] Loaded {} active symbols from database", activeSymbols.size());

        // Step 2: Initialize price cache with zeros (real prices fetched async)
        activeSymbols.forEach(s -> priceCache.put(s.getSymbol(), BigDecimal.ZERO));
        log.info("[LIFECYCLE] Price cache initialized for {} symbols", priceCache.size());

        // Step 3: Validate config
        log.info("[LIFECYCLE] Exchange URL: {}", config.exchangeUrl());
        log.info("[LIFECYCLE] Connection timeout: {}", config.connectionTimeout());

        // Step 4: Mark as connected (real app would connect to exchange here)
        connected = true;
        log.info("[LIFECYCLE] @PostConstruct COMPLETE — service ready");
    }

    /**
     * Phase 9a: @PreDestroy — runs on graceful shutdown (SIGTERM).
     * May NOT run on: SIGKILL, JVM crash, prototype beans.
     * Keep it BOUNDED — set a timeout, do not block indefinitely.
     */
    @PreDestroy
    void shutdown() {
        log.info("[LIFECYCLE] @PreDestroy — shutting down PriceFeedService");
        connected = false;
        priceCache.clear();
        log.info("[LIFECYCLE] Disconnected from exchange, cache cleared");
        log.info("[LIFECYCLE] @PreDestroy COMPLETE");
    }

    // ─── Business methods (available only after @PostConstruct) ───

    public BigDecimal getPrice(String symbol) {
        if (!connected) {
            throw new IllegalStateException("PriceFeedService not connected to exchange");
        }
        return priceCache.getOrDefault(symbol, BigDecimal.ZERO);
    }

    public void updatePrice(String symbol, BigDecimal price) {
        priceCache.put(symbol, price);
        log.debug("Price updated: {} = Rs.{}", symbol, price);
    }

    public boolean isConnected() {
        return connected;
    }

    public int getCachedSymbolCount() {
        return priceCache.size();
    }
}
