package com.bank.pricefeed.health;

import com.bank.pricefeed.service.PriceFeedService;
import lombok.RequiredArgsConstructor;
import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.stereotype.Component;

@Component
@RequiredArgsConstructor
public class ExchangeFeedHealthIndicator implements HealthIndicator {

    private final PriceFeedService priceFeedService;

    @Override
    public Health health() {
        if (priceFeedService.isConnected()) {
            return Health.up()
                .withDetail("exchange", "NSE")
                .withDetail("cachedSymbols", priceFeedService.getCachedSymbolCount())
                .build();
        }
        return Health.down()
            .withDetail("exchange", "NSE")
            .withDetail("error", "not connected")
            .build();
    }
}
