class PriceFeedServiceTest {

    @Mock SymbolRepository symbolRepo;

    PriceFeedService service;

    @BeforeEach
    void setUp() {
        PriceFeedConfig config = new PriceFeedConfig(
            "https://api.nse-test.com", Duration.ofSeconds(5),
            Duration.ofSeconds(60), 3);

        when(symbolRepo.findByActiveTrue()).thenReturn(List.of(
            new Symbol("RELIANCE", "Reliance", "NSE", "Energy"),
            new Symbol("TCS", "TCS", "NSE", "IT")));

        service = new PriceFeedService(symbolRepo, config);
        service.init(); // manually call @PostConstruct in unit test
