package com.bank.fraud.service;

import com.bank.fraud.dto.TransferRequest;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.bank.fraud.event.TransferCompletedEvent;

@Service
@RequiredArgsConstructor
@Slf4j
public class TransferService {

    // Depends on FraudCheckService AND TransactionHistoryService — no cycle!
    private final FraudCheckService fraudCheckService;
    private final TransactionHistoryService historyService;
    private final ApplicationEventPublisher eventPublisher;

    @Transactional
    public String transfer(TransferRequest request) {
        log.info("Transfer request: Rs.{} from {} to {}",
            request.amount(), request.fromAccountId(), request.toAccountId());

        // Step 1: Fraud check (uses historyService internally — no circular dep)
        boolean safe = fraudCheckService.isSafeTransfer(request.fromAccountId(), request.amount());
        if (!safe) {
            log.warn("BLOCKED: Transfer from {} rejected by fraud check", request.fromAccountId());
            return "REJECTED";
        }

        // Step 2: Process transfer (simplified — real app would debit/credit accounts)
        log.info("Transfer APPROVED");

        // Step 3: Record in history
        historyService.recordTransfer(
            request.fromAccountId(), request.toAccountId(), request.amount());

        // Step 4: Publish event (event-driven decoupling — listeners react independently)
        eventPublisher.publishEvent(new TransferCompletedEvent(
            request.fromAccountId(), request.toAccountId(), request.amount()));

        return "COMPLETED";
    }
}
