// ❌ CONSTRUCTOR cycle → BeanCurrentlyInCreationException at startup
@Service class AccountService {
  AccountService(TransactionService ts){ ... }      // needs TS to build
}
@Service class TransactionService {
  TransactionService(AccountService as){ ... }      // needs AS to build → deadlock
}

// ✅ FIX 1: @Lazy breaks the cycle (injects proxy, resolved on first use)
@Service class AccountService {
  AccountService(@Lazy TransactionService ts){ this.ts = ts; }
}

// ✅ FIX 2 (best): extract shared logic into a third bean — no cycle
@Service class BalanceCalculator { Money compute(...){...} }
@Service class AccountService     { AccountService(BalanceCalculator c){...} }
@Service class TransactionService { TransactionService(BalanceCalculator c){...} }

// 3-level cache (setter/field injection path):
//   getSingleton: L1 miss → L2 miss → L3 factory.getObject()
//     → put early ref in L2 → finish populate → promote to L1
