package com.bank.loan.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.math.RoundingMode;

@Service
@Slf4j
public class RiskAssessmentService {

    @Value("${loan.base-interest-rate:8.5}")
    private BigDecimal baseRate;

    /**
     * Calculate interest rate based on credit score.
     * Higher score = lower rate. Lower score = higher rate.
     */
    public BigDecimal calculateInterestRate(int creditScore) {
        BigDecimal adjustment;
        if (creditScore >= 750) {
            adjustment = new BigDecimal("-1.0");   // excellent — discount
        } else if (creditScore >= 700) {
            adjustment = BigDecimal.ZERO;            // good — base rate
        } else {
            adjustment = new BigDecimal("2.0");     // fair — premium
        }
        BigDecimal rate = baseRate.add(adjustment).setScale(2, RoundingMode.HALF_UP);
        log.info("Interest rate for score {}: {}% (base {} + adjustment {})",
            creditScore, rate, baseRate, adjustment);
        return rate;
    }
}
