        return currentPrice != null
            ? currentPrice.multiply(BigDecimal.valueOf(quantity))
            : avgBuyPrice.multiply(BigDecimal.valueOf(quantity));
    }

    public BigDecimal getProfitLoss() {
        if (currentPrice == null) return BigDecimal.ZERO;
        return currentPrice.subtract(avgBuyPrice).multiply(BigDecimal.valueOf(quantity));
    }

    public String getAccountId() { return accountId; }
    public String getSymbol() { return symbol; }
    public int getQuantity() { return quantity; }
    public BigDecimal getAvgBuyPrice() { return avgBuyPrice; }
