public class PortfolioService {

    private final PortfolioRepository portfolioRepo;

    // No @Autowired — single constructor auto-detected by Spring 4.3+
    // No @Qualifier — @Primary (JpaPortfolioRepository) is injected
    public PortfolioService(PortfolioRepository portfolioRepo) {
        this.portfolioRepo = portfolioRepo;
        log.info("PortfolioService using: {} (auto-detected constructor, @Primary resolved)",
            portfolioRepo.getSourceName());
    }

    public PortfolioSummary getPortfolio(String accountId) {
        List<Holding> holdings = portfolioRepo.findByAccountId(accountId);

        List<PortfolioSummary.HoldingDetail> details = holdings.stream()
            .map(h -> new PortfolioSummary.HoldingDetail(
                h.getSymbol(), h.getQuantity(), h.getAvgBuyPrice(),
                h.getCurrentPrice(), h.getMarketValue(), h.getProfitLoss()))
            .toList();

        BigDecimal totalValue = holdings.stream()
            .map(Holding::getMarketValue)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        BigDecimal totalPL = holdings.stream()
            .map(Holding::getProfitLoss)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        return new PortfolioSummary(accountId, holdings.size(), totalValue, totalPL, details);
    }
}
