// *** THREAD-SAFE: No mutable instance fields. All state in local variables or ConcurrentHashMap ***
package com.bank.matching.service;

import com.bank.matching.dto.*;
import com.bank.matching.model.TradeOrder;
import com.bank.matching.repository.OrderRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;

@Service
@RequiredArgsConstructor
@Slf4j
public class OrderMatchingService {

    private final OrderRepository orderRepo;
    private final ExchangePriceService priceService;

    // Thread-safe counter: AtomicInteger for shared mutable state
    private final AtomicInteger matchCount = new AtomicInteger(0);

    // NO mutable instance fields like: private String lastOrderId; ← RACE CONDITION!

    @Transactional
    public OrderResponse placeOrder(OrderRequest request) {
        // ALL mutable state in LOCAL VARIABLES — thread-safe (each thread has own stack)
        String orderId = "ORD-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
        String threadName = Thread.currentThread().getName();

        log.info("[{}] Placing order {} — {} {} {} @ Rs.{}",
            threadName, orderId, request.side(), request.quantity(), request.symbol(), request.price());

        // Create order
        TradeOrder order = new TradeOrder(orderId, request.accountId(), request.symbol(),
            request.side(), request.quantity(), request.price());
        orderRepo.save(order);

        // Try to match with opposite side (pessimistic lock prevents double-match)
        String oppositeSide = "BUY".equals(request.side()) ? "SELL" : "BUY";
        var matchOpt = orderRepo.findMatchingOrder(
            request.symbol(), oppositeSide, request.quantity(), request.price());

        if (matchOpt.isPresent()) {
            TradeOrder matched = matchOpt.get();
            order.markMatched();
            matched.markMatched();
            orderRepo.save(order);
            orderRepo.save(matched);

            int totalMatches = matchCount.incrementAndGet(); // atomic — thread-safe
            log.info("[{}] MATCHED: {} with {} (total matches: {})",
                threadName, orderId, matched.getOrderId(), totalMatches);

            return new OrderResponse(orderId, request.symbol(), request.side(),
                request.quantity(), request.price(), "MATCHED", matched.getOrderId());
        }

        log.info("[{}] No match found — order {} queued", threadName, orderId);
        return new OrderResponse(orderId, request.symbol(), request.side(),
            request.quantity(), request.price(), "PENDING", null);
    }

    public int getTotalMatches() { return matchCount.get(); }
}
