package com.bank.payment.model;

import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.config.ConfigurableBeanFactory;
import org.springframework.context.annotation.Scope;
import org.springframework.stereotype.Component;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;

@Component
@Scope(ConfigurableBeanFactory.SCOPE_PROTOTYPE)  // NEW instance per getBean/injection
@Getter
@Setter
@Slf4j
public class PaymentTransaction {

    private static final AtomicInteger INSTANCE_COUNTER = new AtomicInteger(0);
    private final int instanceId;

    private String paymentId;
    private String fromAccountId;
    private String toAccountId;
    private BigDecimal amount;
    private PaymentMethod method;
    private String status;
    private LocalDateTime createdAt;

    public PaymentTransaction() {
        this.instanceId = INSTANCE_COUNTER.incrementAndGet();
        this.paymentId = "PAY-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
        this.status = "INITIATED";
        this.createdAt = LocalDateTime.now();
        log.debug("PaymentTransaction #{} created (prototype — new instance)", instanceId);
    }

    public void initiate(String from, String to, BigDecimal amount, PaymentMethod method) {
        this.fromAccountId = from;
        this.toAccountId = to;
        this.amount = amount;
        this.method = method;
    }

    public void complete() {
        this.status = "COMPLETED";
    }

    public void fail(String reason) {
        this.status = "FAILED";
    }
}
