// SERVICE layer — business logic ONLY. No HTTP. No direct SQL.
package com.bank.statement.service;

import com.bank.statement.dto.*;
import com.bank.statement.model.Transaction;
import com.bank.statement.repository.TransactionRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class StatementService {

    private final TransactionRepository txnRepo; // ONLY dependency — clean separation

    @Transactional(readOnly = true)
    public StatementResponse generateStatement(StatementRequest request) {
        log.info("Generating statement for {} from {} to {}",
            request.accountId(), request.fromDate(), request.toDate());

        // Delegate data access to repository
        List<Transaction> transactions = txnRepo
            .findByAccountIdAndTxnDateBetweenOrderByTxnDateDesc(
                request.accountId(), request.fromDate(), request.toDate());

        // Business logic: calculate totals
        BigDecimal totalCredits = txnRepo.sumCredits(
            request.accountId(), request.fromDate(), request.toDate());
        BigDecimal totalDebits = txnRepo.sumDebits(
            request.accountId(), request.fromDate(), request.toDate());

        if (totalCredits == null) totalCredits = BigDecimal.ZERO;
        if (totalDebits == null) totalDebits = BigDecimal.ZERO;

        BigDecimal netChange = totalCredits.subtract(totalDebits);
        BigDecimal closingBalance = transactions.isEmpty()
            ? BigDecimal.ZERO
            : transactions.getFirst().getBalanceAfter();

        // Map entities to DTOs (never expose entities directly)
        List<StatementResponse.TransactionLine> lines = transactions.stream()
            .map(t -> new StatementResponse.TransactionLine(
                t.getTxnId(), t.getTxnDate(), t.getType(),
                t.getAmount(), t.getDescription(), t.getBalanceAfter()))
            .toList();

        log.info("Statement generated: {} transactions, credits={}, debits={}",
            transactions.size(), totalCredits, totalDebits);

        return new StatementResponse(
            request.accountId(), request.fromDate(), request.toDate(),
            transactions.size(), totalCredits, totalDebits, netChange,
            closingBalance, lines);
    }
}
