package com.bank.interest.service;

import com.bank.interest.cache.CacheService;
import com.bank.interest.dto.*;
import com.bank.interest.fraud.FraudCheckService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Optional;

@Service
@RequiredArgsConstructor
@Slf4j
public class InterestService {

    private final RateProviderService rateProvider;
    private final CacheService cacheService;
    private final Optional<FraudCheckService> fraudCheck; // Optional — may not exist in dev!

    public InterestResponse calculate(InterestRequest request) {
        log.info("Calculating interest for {} | principal={} | tenure={}m",
            request.accountId(), request.principal(), request.tenureMonths());

        // Optional fraud check (only exists when property=true)
        fraudCheck.ifPresent(fc -> {
            if (!fc.isSafe(request.accountId(), request.principal())) {
                throw new IllegalStateException("Fraud check failed");
            }
        });

        BigDecimal rate = rateProvider.getCurrentRate("FD");
        BigDecimal years = BigDecimal.valueOf(request.tenureMonths()).divide(BigDecimal.valueOf(12), 4, RoundingMode.HALF_UP);
        BigDecimal interest = request.principal().multiply(rate).multiply(years).divide(new BigDecimal("100"), 2, RoundingMode.HALF_UP);
        BigDecimal maturity = request.principal().add(interest);

        log.info("Rate: {}% from {} | Interest: Rs.{} | Maturity: Rs.{}",
            rate, rateProvider.getSourceName(), interest, maturity);

        return new InterestResponse(
            request.accountId(), request.principal(), request.tenureMonths(),
            rate, interest, maturity, rateProvider.getSourceName(), cacheService.getCacheType());
    }
}
