import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class SettlementService {

    private final TradeRepository tradeRepo;

    @Transactional
    public int settlePendingTrades() {
        List<Trade> pending = tradeRepo.findByStatus("PENDING");
        log.info("Found {} pending trades to settle", pending.size());
        pending.forEach(trade -> {
            trade.settle();
            tradeRepo.save(trade);
            log.info("Settled: {} {} x{} @ Rs.{}", trade.getTradeId(),
                trade.getSymbol(), trade.getQuantity(), trade.getPrice());
        });
        return pending.size();
    }
}
