import jakarta.validation.constraints.*;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.validation.annotation.Validated;
import java.math.BigDecimal;
import java.time.Duration;
import java.util.List;

@ConfigurationProperties(prefix = "forex")
@Validated  // triggers Bean Validation at startup — fails fast if invalid
public record ForexConfig(

    @NotBlank
    String baseCurrency,            // forex.base-currency → "INR"

    @NotEmpty
    List<String> supportedCurrencies,  // forex.supported-currencies → [USD, EUR, GBP]

    @NotNull
    Duration cacheTtl,              // forex.cache-ttl → Duration.ofMinutes(5)

    @NotBlank
    String rateProvider,            // forex.rate-provider → "live" or "fixed"

    String apiUrl,                  // forex.api-url (null in dev — not needed for fixed rates)

    String apiKey,                  // forex.api-key (from K8s secret in prod)

    @DecimalMin("1000")
    BigDecimal maxConversionAmount  // forex.max-conversion-amount

) {
    // Constructor binding: all fields final, immutable.
    // Relaxed binding: cache-ttl → cacheTtl, max-conversion-amount → maxConversionAmount
    // If @NotBlank baseCurrency is missing → startup FAILS with clear error message
}
