    public void recordEvent(AuditEvent event) {
        String traceId = MDC.get("traceId");
        String userId = MDC.get("userId");

        // GOOD: parameterized logging — string built ONLY if level enabled
        log.info("Audit event: action={}, entity={}/{}, account={}",
            event.action(), event.entityType(), event.entityId(),
            PiiMasker.maskAccountId(event.accountId()));  // PII MASKED!

        // GOOD: debug details only when DEBUG is enabled
        log.debug("Event details: {}", event.details());

        try {
            AuditLog auditLog = new AuditLog(
                traceId, userId, event.action(),
                event.entityType(), event.entityId(), event.details());
            auditRepo.save(auditLog);

            log.info("Audit log saved: traceId={}, action={}", traceId, event.action());

        } catch (Exception e) {
            // GOOD: exception as LAST argument — preserves full stack trace
            log.error("Failed to save audit log for action {}", event.action(), e);
            // NEVER: log.error("Failed: " + e.getMessage()); ← loses stack trace!
            // NEVER: e.printStackTrace(); ← goes to stderr, not logging framework!
            throw e;
        }
    }
}
