// @Around advice: measures and logs execution time for @LogExecutionTime methods
package com.bank.compliance.aspect;

import com.bank.compliance.annotation.LogExecutionTime;
import lombok.extern.slf4j.Slf4j;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.*;
import org.aspectj.lang.reflect.MethodSignature;
import org.springframework.stereotype.Component;

@Aspect
@Component
@Slf4j
public class ExecutionTimeAspect {

    @Around("@annotation(logExecutionTime)")
    public Object measureTime(ProceedingJoinPoint pjp, LogExecutionTime logExecutionTime) throws Throwable {
        String methodName = pjp.getSignature().toShortString();
        String label = logExecutionTime.value().isEmpty() ? methodName : logExecutionTime.value();

        log.info("[TIMING] ENTER: {}", label);
        long start = System.nanoTime();

        try {
            Object result = pjp.proceed();  // CALL the actual method
            long elapsedMs = (System.nanoTime() - start) / 1_000_000;
            log.info("[TIMING] EXIT: {} completed in {}ms", label, elapsedMs);
            return result;
        } catch (Exception e) {
            long elapsedMs = (System.nanoTime() - start) / 1_000_000;
            log.error("[TIMING] FAILED: {} threw {} in {}ms", label, e.getClass().getSimpleName(), elapsedMs);
            throw e;  // re-throw — NEVER swallow!
        }
    }
}
