import com.bank.compliance.annotation.Auditable;
import lombok.extern.slf4j.Slf4j;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.*;
import org.slf4j.MDC;
import org.springframework.stereotype.Component;
import java.util.Arrays;

@Aspect
@Component
@Slf4j
public class AuditAspect {

    @Around("@annotation(auditable)")
    public Object audit(ProceedingJoinPoint pjp, Auditable auditable) throws Throwable {
        String user = MDC.get("userId");
        String traceId = MDC.get("traceId");
        String method = pjp.getSignature().toShortString();
        String args = Arrays.toString(pjp.getArgs());

        log.info("[AUDIT] action={}, method={}, user={}, traceId={}, args={}",
            auditable.action(), method, user, traceId, args);

        try {
            Object result = pjp.proceed();
            log.info("[AUDIT] action={} SUCCEEDED, result={}", auditable.action(), result);
            return result;
        } catch (Exception e) {
            log.error("[AUDIT] action={} FAILED: {}", auditable.action(), e.getMessage(), e);
            throw e;
        }
    }
}
