package com.bank.marketdata.cache;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.cache.*;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.serializer.*;
import java.time.Duration;
import java.util.Map;

@Configuration
@EnableCaching
public class RedisCacheConfig {

    @Bean
    RedisCacheManager cacheManager(RedisConnectionFactory factory) {
        // JSON serializer — human-readable, version-tolerant (unlike Java serialization)
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());

        RedisSerializationContext.SerializationPair<Object> jsonSerializer =
            RedisSerializationContext.SerializationPair.fromSerializer(
                new GenericJackson2JsonRedisSerializer(mapper));

        // Default cache config: 5 min TTL, JSON values
        RedisCacheConfiguration defaultConfig = RedisCacheConfiguration.defaultCacheConfig()
            .entryTtl(Duration.ofMinutes(5))
            .serializeValuesWith(jsonSerializer)
            .disableCachingNullValues();

        // Per-cache TTL customization (different data = different staleness tolerance)
        Map<String, RedisCacheConfiguration> cacheConfigs = Map.of(
            "prices",      defaultConfig.entryTtl(Duration.ofSeconds(30)),   // 30s — prices change fast
            "companyInfo", defaultConfig.entryTtl(Duration.ofHours(24))      // 24h — rarely changes
        );

        return RedisCacheManager.builder(factory)
            .cacheDefaults(defaultConfig)
            .withInitialCacheConfigurations(cacheConfigs)
            .build();
    }
}
