package com.bank.kyc.service;

import com.bank.kyc.dto.*;
import com.bank.kyc.exception.KycNotFoundException;
import com.bank.kyc.model.CustomerKyc;
import com.bank.kyc.repository.CustomerKycRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class KycVerificationService {

    private final CustomerKycRepository kycRepo;

    @Transactional
    public KycResponse submitKyc(KycRequest request) {
        if (kycRepo.existsByPanNumber(request.panNumber())) {
            throw new IllegalArgumentException("PAN already registered: " + request.panNumber());
        }

        String kycId = "KYC-" + UUID.randomUUID().toString().substring(0, 6).toUpperCase();
        CustomerKyc kyc = new CustomerKyc(kycId, request.customerId(), request.fullName(), request.panNumber());
        kycRepo.save(kyc);
        log.info("KYC submitted: {} for customer {}", kycId, request.customerId());
        return KycResponse.from(kyc);
    }

    @Transactional
    public KycResponse verifyKyc(String customerId) {
        CustomerKyc kyc = kycRepo.findByCustomerId(customerId)
            .orElseThrow(() -> new KycNotFoundException(customerId));
        kyc.verify();
        kycRepo.save(kyc);
        log.info("KYC verified: {} for customer {}", kyc.getKycId(), customerId);
        return KycResponse.from(kyc);
    }

    public KycResponse getKyc(String customerId) {
        return kycRepo.findByCustomerId(customerId)
            .map(KycResponse::from)
            .orElseThrow(() -> new KycNotFoundException(customerId));
    }
}
