// TEST 1: UNIT TEST — Mockito, NO Spring, ~50ms
// ═══════════════════════════════════════════════════
// File: src/test/java/com/bank/kyc/service/KycVerificationServiceTest.java

package com.bank.kyc.service;

import com.bank.kyc.dto.*;
import com.bank.kyc.exception.KycNotFoundException;
import com.bank.kyc.model.CustomerKyc;
import com.bank.kyc.repository.CustomerKycRepository;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)  // NO Spring context — fast!
@DisplayName("KYC Verification Service — Unit Tests")
class KycVerificationServiceTest {

    @Mock CustomerKycRepository kycRepo;     // full stub — returns defaults
    @InjectMocks KycVerificationService kycService;  // creates with mock repo

    // ─── @BeforeEach: fresh setup per test ───
    @BeforeEach
    void setUp() {
        // Mockito resets mocks between tests automatically with @ExtendWith
    }

    // ─── HAPPY PATH ───
    @Test
    @DisplayName("should submit KYC successfully")
    void shouldSubmitKyc() {
        when(kycRepo.existsByPanNumber("ABCDE1234F")).thenReturn(false);
        when(kycRepo.save(any(CustomerKyc.class))).thenAnswer(i -> i.getArgument(0));

        KycResponse response = kycService.submitKyc(
            new KycRequest("CUST003", "Amit Singh", "ABCDE1234F"));

        assertThat(response.customerId()).isEqualTo("CUST003");
        assertThat(response.status()).isEqualTo("PENDING");

        // ArgumentCaptor: inspect what was saved
        ArgumentCaptor<CustomerKyc> captor = ArgumentCaptor.forClass(CustomerKyc.class);
        verify(kycRepo).save(captor.capture());
        assertThat(captor.getValue().getFullName()).isEqualTo("Amit Singh");
        assertThat(captor.getValue().getPanNumber()).isEqualTo("ABCDE1234F");
    }

    @Test
    @DisplayName("should verify KYC and update status")
    void shouldVerifyKyc() {
        CustomerKyc kyc = new CustomerKyc("KYC-001", "CUST001", "Rajesh", "PAN123");
        when(kycRepo.findByCustomerId("CUST001")).thenReturn(Optional.of(kyc));
        when(kycRepo.save(any())).thenAnswer(i -> i.getArgument(0));

        KycResponse response = kycService.verifyKyc("CUST001");

        assertThat(response.status()).isEqualTo("VERIFIED");
        verify(kycRepo).save(any(CustomerKyc.class));
    }

    // ─── FAILURE PATHS (equally important!) ───
    @Test
    @DisplayName("should reject duplicate PAN")
    void shouldRejectDuplicatePan() {
        when(kycRepo.existsByPanNumber("ABCDE1234F")).thenReturn(true);

        assertThatThrownBy(() -> kycService.submitKyc(
                new KycRequest("CUST003", "Amit", "ABCDE1234F")))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("PAN already registered");

        verify(kycRepo, never()).save(any()); // must NOT save on duplicate
    }

    @Test
    @DisplayName("should throw when customer not found")
    void shouldThrowWhenNotFound() {
        when(kycRepo.findByCustomerId("UNKNOWN")).thenReturn(Optional.empty());

        assertThatThrownBy(() -> kycService.verifyKyc("UNKNOWN"))
            .isInstanceOf(KycNotFoundException.class)
            .hasMessageContaining("UNKNOWN");
    }

    // ─── VERIFY NO MORE INTERACTIONS ───
    @Test
    @DisplayName("should not call DB unnecessarily")
    void shouldNotCallDbUnnecessarily() {
        when(kycRepo.existsByPanNumber(anyString())).thenReturn(true);
        assertThatThrownBy(() -> kycService.submitKyc(
            new KycRequest("X", "Y", "Z123456789")));
        verify(kycRepo, never()).save(any());
        verifyNoMoreInteractions(kycRepo);
    }
}
