// Returns structured JSON for 401 instead of default HTML
package com.bank.account.security;

import jakarta.servlet.http.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.MediaType;
import org.springframework.security.core.AuthenticationException;
import org.springframework.security.web.AuthenticationEntryPoint;
import org.springframework.stereotype.Component;
import java.io.IOException;

@Component
@Slf4j
public class CustomAuthEntryPoint implements AuthenticationEntryPoint {

    @Override
    public void commence(HttpServletRequest req, HttpServletResponse resp,
                          AuthenticationException ex) throws IOException {
        log.warn("Unauthorized access to {}: {}", req.getRequestURI(), ex.getMessage());
        resp.setContentType(MediaType.APPLICATION_JSON_VALUE);
        resp.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
        resp.getWriter().write("""
            {"error":"Unauthorized","message":"%s","path":"%s"}
            """.formatted(ex.getMessage(), req.getRequestURI()));
    }
}
