import org.springframework.transaction.annotation.Transactional;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class UpiService {

    private final UpiTransactionRepository txnRepo;  // JPA — for CRUD

    @Transactional
    public UpiPaymentResponse pay(UpiPaymentRequest request) {
        if (request.senderVpa().equals(request.receiverVpa())) {
            throw new IllegalArgumentException("Cannot send to yourself");
        }

        String txnId = "UPI-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
        UpiTransaction txn = new UpiTransaction(
            txnId, request.senderVpa(), request.receiverVpa(), request.amount(), request.note());
        txn.succeed();  // simplified — real app calls NPCI
        txnRepo.save(txn);

        log.info("UPI payment: {} → {} Rs.{} [{}]",
            request.senderVpa(), request.receiverVpa(), request.amount(), txnId);
        return UpiPaymentResponse.from(txn);
    }
}
