// Bounded thread pool for @Async — NEVER use unbounded SimpleAsyncTaskExecutor
package com.bank.trading.async;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;
import java.util.concurrent.Executor;

@Configuration
@EnableAsync
public class AsyncConfig {

    @Bean("postTradeExecutor")
    Executor postTradeExecutor(
            @Value("${async.core-pool-size:5}") int core,
            @Value("${async.max-pool-size:20}") int max,
            @Value("${async.queue-capacity:100}") int queue) {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(core);
        executor.setMaxPoolSize(max);
        executor.setQueueCapacity(queue);          // BOUNDED — prevents OOM
        executor.setThreadNamePrefix("post-trade-");
        executor.setWaitForTasksToCompleteOnShutdown(true);
        executor.setAwaitTerminationSeconds(30);
        return executor;
    }
}
