    public void processAfterTrade(String tradeId, String accountId) {
        log.info("[ASYNC] Post-trade processing for {} (does NOT block response)", tradeId);
        // Non-critical work:
        // 1. Send confirmation notification
        // 2. Update portfolio analytics
        // 3. Log to audit trail
        // 4. Trigger risk recalculation
        try { Thread.sleep(500); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        log.info("[ASYNC] Post-trade complete for {}", tradeId);
    }
}
