package com.bank.trading.service;

import com.bank.trading.async.PostTradeProcessor;
import com.bank.trading.dto.*;
import com.bank.trading.model.Trade;
import com.bank.trading.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class TradeExecutionService {

    private final TradeRepository tradeRepo;
    private final PriceService priceService;       // cached — Redis
    private final PostTradeProcessor postProcessor; // async — does not block

    @Transactional
    public TradeResponse executeTrade(TradeRequest request) {
        long start = System.nanoTime();
        String tradeId = "TRD-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();

        // Step 1: Get price (from Redis cache — ~1ms, not exchange API ~200ms)
        priceService.getLatestPrice(request.symbol());

        // Step 2: Create and save trade (DB — ~5ms with index)
        Trade trade = new Trade(tradeId, request.accountId(), request.symbol(),
            request.side(), request.quantity(), request.price());
        trade.execute();
        tradeRepo.save(trade);

        // Step 3: Async post-processing (notification, analytics — does NOT block response)
        postProcessor.processAfterTrade(tradeId, request.accountId());

        long elapsed = (System.nanoTime() - start) / 1_000_000;
        log.info("Trade {} executed in {}ms (async work runs in background)", tradeId, elapsed);

        return TradeResponse.from(trade);
    }
}
