// SOLVES: MDC/SecurityContext lost in @Async threads (ThreadLocal is per-thread)
// Copies MDC context from the CALLING thread to the ASYNC worker thread
package com.bank.orchestrator.async;

import org.slf4j.MDC;
import org.springframework.core.task.TaskDecorator;
import java.util.Map;

public class MdcTaskDecorator implements TaskDecorator {

    @Override
    public Runnable decorate(Runnable runnable) {
        // Capture MDC from the CALLING thread (request thread)
        Map<String, String> contextMap = MDC.getCopyOfContextMap();

        return () -> {
            try {
                // Set MDC in the ASYNC worker thread
                if (contextMap != null) MDC.setContextMap(contextMap);
                runnable.run();
            } finally {
                MDC.clear();  // clean up worker thread
            }
        };
    }
}
