    @Async("settlementExecutor")
    public void sendSettlementNotification(String settlementId, String accountId) {
        // This runs on async thread — MDC propagated by MdcTaskDecorator
        String traceId = MDC.get("traceId");
        log.info("[ASYNC] [{}] Sending notification for {} to {}",
            traceId, settlementId, accountId);
        // Send email/SMS/push
        try { Thread.sleep(300); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        log.info("[ASYNC] [{}] Notification sent for {}", traceId, settlementId);
    }
}
