package com.bank.orchestrator.service;

import com.bank.orchestrator.dto.*;
import com.bank.orchestrator.model.Settlement;
import com.bank.orchestrator.repository.SettlementRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class SettlementOrchestrator {

    private final SettlementRepository settlementRepo;
    private final NotificationService notificationService;  // SEPARATE bean — @Async works!

    /**
     * @Transactional: proxy starts transaction.
     * RULE: must be PUBLIC — private @Transactional is silently ignored!
     * RULE: must be called from OUTSIDE this class — self-invocation bypasses proxy!
     */
    @Transactional
    public SettlementResponse settle(SettlementRequest request) {
        String settlementId = "STL-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
        log.info("Settling trade {} → settlement {}", request.tradeId(), settlementId);

        Settlement settlement = new Settlement(
            settlementId, request.tradeId(), request.accountId(), request.amount());
        settlement.complete();
        settlementRepo.save(settlement);

        // @Async notification — runs on separate thread AFTER this method returns
        // Works because notificationService is a SEPARATE bean (call goes through proxy)
        notificationService.sendSettlementNotification(settlementId, request.accountId());

        // BAD EXAMPLE (self-invocation — @Async would run synchronously):
        // this.sendNotification(settlementId); // same class → bypasses proxy → runs on THIS thread!

        return SettlementResponse.from(settlement);
    }

    // BAD: @Transactional on private method — SILENTLY IGNORED by CGLIB proxy
    // @Transactional
    // private void processInternal(Settlement s) { /* proxy cannot override private */ }
}
