            .map(tick -> {
                BigDecimal price = new BigDecimal("2450")
                    .add(BigDecimal.valueOf(Math.random() * 20 - 10))
                    .setScale(2, RoundingMode.HALF_UP);
                BigDecimal change = price.subtract(new BigDecimal("2450"));
                return new PriceUpdate(symbol, price, change, LocalDateTime.now());
            })
            .doOnSubscribe(s -> log.info("Client subscribed to {} price feed", symbol))
            .doOnCancel(() -> log.info("Client disconnected from {} price feed", symbol));
    }
