import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
@RequiredArgsConstructor
@Slf4j
public class DividendScheduler {

    private final DividendService dividendService;

    // CRON: 3 PM weekdays — like EOD settlement
    @Scheduled(cron = "${dividend.payout-schedule}")
    public void scheduledPayout() {
        log.info("[SCHEDULER] Cron triggered: processing declared dividends");
        int count = dividendService.processDeclaredDividends();
        log.info("[SCHEDULER] Processed {} dividends", count);
    }

    // fixedRate: fires every 60s regardless of how long previous execution took
    // If task takes 90s, next fires immediately after (overlap possible — use @Async to prevent)
    @Scheduled(fixedRate = 60000)
    public void healthCheck() {
        log.debug("[SCHEDULER] fixedRate: health ping every 60s");
    }

    // fixedDelay: waits 30s AFTER previous execution completes — no overlap
    @Scheduled(fixedDelay = 30000, initialDelay = 10000)
    public void retryFailedPayouts() {
        log.debug("[SCHEDULER] fixedDelay: retry failed payouts (waits after completion)");
    }
}
